"use strict";
import { useEffect, useState } from "react";
import { useAccount } from "wagmi";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
function calculateTotalValueUSD(fees, bribes) {
  const totalRewards = fees.length + bribes.length;
  return totalRewards > 0 ? "0.00" : "0";
}
async function getTokenInfo(tokenAddress, provider) {
  try {
    const tokenContract = new Contract(tokenAddress, [
      "function symbol() external view returns (string)",
      "function decimals() external view returns (uint8)"
    ], provider);
    const [symbol, decimals] = await Promise.all([
      tokenContract.symbol(),
      tokenContract.decimals()
    ]);
    return { symbol, decimals };
  } catch (error) {
    console.warn(`\u26A0\uFE0F Failed to get token info for ${tokenAddress}:`, error);
    if (tokenAddress.toLowerCase() === "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d") {
      return { symbol: "WETH", decimals: 18 };
    }
    if (tokenAddress.toLowerCase() === "0xb6313be1c20dc222199ec567951abc6b5b64dfd6") {
      return { symbol: "ABX", decimals: 18 };
    }
    return { symbol: "TOKEN", decimals: 18 };
  }
}
export function useVotingRewards(lock) {
  const { address } = useAccount();
  const provider = useEthersProvider({ chainId: UniverseChainId.AbstractTestnet });
  const [rewardData, setRewardData] = useState({
    fees: [],
    bribes: [],
    totalValueUSD: "0",
    canClaim: false,
    isLoading: true,
    claimableContracts: { feeContracts: [], bribeContracts: [] },
    votedPools: []
  });
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  useEffect(() => {
    async function fetchVotingRewards() {
      if (!lock || !address || !provider || !voterAddress || !voterAbi) {
        setRewardData((prev) => ({ ...prev, isLoading: false, votedPools: [] }));
        return;
      }
      try {
        console.log(`\u{1F5F3}\uFE0F [VOTING REWARDS] Fetching rewards for lock ${lock.id}...`);
        const voterContract = new Contract(voterAddress, voterAbi, provider);
        const tokenId = lock.id;
        console.log(`\u{1F4CA} [VOTING REWARDS] Getting pool votes for tokenId ${tokenId}...`);
        const poolVote = [];
        let index = 0;
        while (true) {
          try {
            const pool = await voterContract.poolVote(tokenId, index);
            poolVote.push(pool);
            index++;
            console.log(`\u{1F4CA} [VOTING REWARDS] Found pool at index ${index - 1}: ${pool}`);
          } catch (error) {
            console.log(`\u{1F4CA} [VOTING REWARDS] No more pools found at index ${index}`);
            break;
          }
        }
        console.log(`\u{1F4CA} [VOTING REWARDS] User voted for ${poolVote.length} pools:`, poolVote);
        if (poolVote.length === 0) {
          console.log(`\u{1F4CA} [VOTING REWARDS] No votes found for tokenId ${tokenId}`);
          setRewardData({
            fees: [],
            bribes: [],
            totalValueUSD: "0",
            canClaim: false,
            isLoading: false,
            claimableContracts: { feeContracts: [], bribeContracts: [] },
            votedPools: []
          });
          return;
        }
        const rewardContracts = await Promise.all(
          poolVote.map(async (pool) => {
            try {
              const gauge = await voterContract.gauges(pool);
              const bribeReward = await voterContract.gaugeToBribe(gauge);
              const feeReward = await voterContract.gaugeToFees(gauge);
              console.log(`\u{1F3AF} [VOTING REWARDS] Pool ${pool}:`, { gauge, bribeReward, feeReward });
              return { pool, gauge, bribeReward, feeReward };
            } catch (error) {
              console.warn(`\u26A0\uFE0F [VOTING REWARDS] Failed to get contracts for pool ${pool}:`, error);
              return null;
            }
          })
        );
        const validContracts = rewardContracts.filter((contract) => contract !== null);
        console.log(`\u2705 [VOTING REWARDS] Found ${validContracts.length} valid reward contracts`);
        const votedPools = validContracts.map(({ pool, gauge }) => ({
          poolAddress: pool,
          gaugeAddress: gauge
        }));
        if (validContracts.length === 0) {
          setRewardData({
            fees: [],
            bribes: [],
            totalValueUSD: "0",
            canClaim: false,
            isLoading: false,
            claimableContracts: { feeContracts: [], bribeContracts: [] },
            votedPools: []
          });
          return;
        }
        const allFees = [];
        const allBribes = [];
        const feeContracts = [];
        const bribeContracts = [];
        const rewardAbi = [
          "function rewardsListLength() external view returns (uint256)",
          "function rewards(uint256 index) external view returns (address)",
          "function earned(address token, uint256 tokenId) external view returns (uint256)",
          "function getReward(uint256 tokenId, address[] memory tokens) external"
        ];
        for (const { bribeReward, feeReward } of validContracts) {
          try {
            if (bribeReward !== "0x0000000000000000000000000000000000000000") {
              const bribeContract = new Contract(bribeReward, rewardAbi, provider);
              try {
                const bribeLength = await bribeContract.rewardsListLength();
                console.log(`\u{1F4B0} [BRIBE REWARDS] Found ${bribeLength} bribe token types`);
                for (let i = 0; i < bribeLength; i++) {
                  try {
                    const tokenAddress = await bribeContract.rewards(i);
                    const earnedAmount = await bribeContract.earned(tokenAddress, tokenId);
                    console.log(`\u{1F4B0} [BRIBE REWARDS] Token ${i} (${tokenAddress}): ${earnedAmount.toString()} wei`);
                    if (earnedAmount.gt(0)) {
                      const tokenInfo = await getTokenInfo(tokenAddress, provider);
                      allBribes.push({
                        address: tokenAddress,
                        symbol: tokenInfo.symbol,
                        decimals: tokenInfo.decimals,
                        amount: earnedAmount.toString()
                      });
                      if (!bribeContracts.includes(bribeReward)) {
                        bribeContracts.push(bribeReward);
                      }
                    }
                  } catch (error) {
                    console.warn(`\u26A0\uFE0F [BRIBE REWARDS] Failed to get bribe token ${i}:`, error);
                  }
                }
              } catch (error) {
                console.warn(`\u26A0\uFE0F [BRIBE REWARDS] Failed to process bribe contract ${bribeReward}:`, error);
              }
            }
            if (feeReward !== "0x0000000000000000000000000000000000000000") {
              const feeContract = new Contract(feeReward, rewardAbi, provider);
              try {
                const feeLength = await feeContract.rewardsListLength();
                console.log(`\u{1F4B0} [FEE REWARDS] Found ${feeLength} fee token types`);
                for (let i = 0; i < feeLength; i++) {
                  try {
                    const tokenAddress = await feeContract.rewards(i);
                    const earnedAmount = await feeContract.earned(tokenAddress, tokenId);
                    console.log(`\u{1F4B0} [FEE REWARDS] Token ${i} (${tokenAddress}): ${earnedAmount.toString()} wei`);
                    if (earnedAmount.gt(0)) {
                      const tokenInfo = await getTokenInfo(tokenAddress, provider);
                      allFees.push({
                        address: tokenAddress,
                        symbol: tokenInfo.symbol,
                        decimals: tokenInfo.decimals,
                        amount: earnedAmount.toString()
                      });
                      if (!feeContracts.includes(feeReward)) {
                        feeContracts.push(feeReward);
                      }
                    }
                  } catch (error) {
                    console.warn(`\u26A0\uFE0F [FEE REWARDS] Failed to get fee token ${i}:`, error);
                  }
                }
              } catch (error) {
                console.warn(`\u26A0\uFE0F [FEE REWARDS] Failed to process fee contract ${feeReward}:`, error);
              }
            }
          } catch (error) {
            console.warn(`\u26A0\uFE0F [VOTING REWARDS] Failed to process reward contracts:`, error);
          }
        }
        const totalRewards = allFees.length + allBribes.length;
        const canClaim = totalRewards > 0;
        console.log(`\u2705 [VOTING REWARDS] Summary for lock ${lock.id}:`, {
          totalFees: allFees.length,
          totalBribes: allBribes.length,
          canClaim,
          feeContracts: feeContracts.length,
          bribeContracts: bribeContracts.length
        });
        const totalValueUSD = calculateTotalValueUSD(allFees, allBribes);
        setRewardData({
          fees: allFees,
          bribes: allBribes,
          totalValueUSD,
          canClaim,
          isLoading: false,
          claimableContracts: { feeContracts, bribeContracts },
          votedPools
        });
      } catch (error) {
        console.error("\u274C [VOTING REWARDS] Error fetching voting rewards:", error);
        setRewardData({
          fees: [],
          bribes: [],
          totalValueUSD: "0",
          canClaim: false,
          isLoading: false,
          claimableContracts: { feeContracts: [], bribeContracts: [] },
          votedPools: []
        });
      }
    }
    fetchVotingRewards();
  }, [lock, address, provider, voterAddress, voterAbi]);
  return rewardData;
}
export function formatRewardAmount(amount, decimals) {
  const value = parseFloat(amount) / Math.pow(10, decimals);
  if (value < 1e-3) return "< 0.001";
  if (value < 1) return value.toFixed(3);
  if (value < 100) return value.toFixed(2);
  return Math.floor(value).toString();
}
export function getRewardTokenArrays(fees, bribes) {
  return {
    feeTokens: fees.map((token) => token.address),
    bribeTokens: bribes.map((token) => token.address)
  };
}
