"use strict";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { useAccount } from "hooks/useAccount";
import { useSimpleAbstractPositions } from "hooks/useSimpleAbstractPositions";
import LiquidityHowItWorksModal from "pages/Liquidity/components/LIquidityHowItWorksModal";
import { useMemo } from "react";
import { Flex, Text } from "ui/src";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import LiquidityRewardsTopPart from "./LiquidityRewardsTopPart";
import PoolLiquidityRewards from "./PoolLiquidityRewards";
export default function LiquidityRewards() {
  const { address } = useAccount();
  const { defaultChainId } = useEnabledChains();
  const { data: positionsData, isLoading } = useSimpleAbstractPositions({
    address,
    chainIds: [defaultChainId || UniverseChainId.Sepolia],
    positionStatuses: [PositionStatus.IN_RANGE, PositionStatus.OUT_OF_RANGE],
    protocolVersions: [ProtocolVersion.V2, ProtocolVersion.V3]
  });
  const groupedPositions = useMemo(() => {
    const allPositions = positionsData?.pages.flatMap((page) => page.positions) || [];
    console.log(`\u{1F4BC} [USER POSITIONS] Found ${allPositions.length} positions:`);
    allPositions.forEach((position, index) => {
      console.log(`\u{1F4CD} Position ${index + 1}:`, {
        poolId: position.poolId,
        version: position.version,
        tokens: `${position.currency0Amount.currency.symbol}-${position.currency1Amount.currency.symbol}`,
        tokenId: position.tokenId || "V2 position",
        amounts: `${position.currency0Amount.toFixed(4)} ${position.currency0Amount.currency.symbol} + ${position.currency1Amount.toFixed(4)} ${position.currency1Amount.currency.symbol}`,
        isStaked: position.isStaked,
        hasGaugeStake: position.hasGaugeStake,
        isGaugePosition: position.isGaugePosition
      });
    });
    const positionGroups = /* @__PURE__ */ new Map();
    allPositions.forEach((position) => {
      const token0Symbol = position.currency0Amount.currency.symbol;
      const token1Symbol = position.currency1Amount.currency.symbol;
      const [tokenA, tokenB] = [token0Symbol, token1Symbol].sort();
      let feeId = "0.30%";
      if (position.feeTier) {
        feeId = (position.feeTier / 1e4).toFixed(2) + "%";
      } else if (position.version === 1) {
        feeId = "0.30%";
      }
      const groupKey = `${tokenA}/${tokenB}-${feeId}-${position.version}`;
      if (!positionGroups.has(groupKey)) {
        positionGroups.set(groupKey, {
          poolKey: groupKey,
          tokenA,
          tokenB,
          feeId,
          version: position.version,
          positions: [],
          // Use first position as representative for pool display
          representative: position
        });
      }
      positionGroups.get(groupKey).positions.push(position);
    });
    return Array.from(positionGroups.values());
  }, [positionsData]);
  const hasPositions = groupedPositions.length > 0;
  return <Flex>
      <LiquidityRewardsTopPart />
      <Flex className="liquidities" mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        {isLoading ? (
    // Show loading state with mock cards
    Array.from({ length: 2 }, (_, index) => <PoolLiquidityRewards key={`loading-${index}`} isLoading={true} />)
  ) : hasPositions ? (
    // Show grouped positions
    groupedPositions.map((poolGroup) => <PoolLiquidityRewards key={poolGroup.poolKey} poolGroup={poolGroup} />)
  ) : (
    // Show empty state
    <Flex
      py={"$spacing48"}
      px={"$spacing24"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      justifyContent="center"
      alignItems="center"
    >
            <Text variant="body2" color={"$neutral2"} textAlign="center">
              No liquidity positions found.{" "}
              <Text variant="body2" color={"$accent1"}>
                Create a new position to start earning rewards.
              </Text>
            </Text>
          </Flex>
  )}
      </Flex>
      <LiquidityHowItWorksModal />
    </Flex>;
}
